function validate([grid]) {
  if (!Array.isArray(grid) || grid.length < 3 || grid.length > 7) return 'grid has 3 to 7 rows.';
  const n = grid.length;
  if (grid.some(line => !Array.isArray(line) || line.length !== n)) return 'grid must be square: n rows of n values.';
  const seen = new Set();
  for (const line of grid) {
    for (const v of line) {
      if (!Number.isInteger(v) || v < 0 || v >= n * n) return 'Each value is a whole number from 0 to n * n - 1.';
      if (seen.has(v)) return 'All values in grid must be different.';
      seen.add(v);
    }
  }
  return null;
}

