function checkValidGrid(grid) {
  const n = grid.length;
  if (grid[0][0] !== 0) {
    return false;
  }

  const position = new Array(n * n);
  for (let row = 0; row < n; row++) {
    for (let col = 0; col < n; col++) {
      position[grid[row][col]] = [row, col];
    }
  }

  for (let step = 1; step < n * n; step++) {
    const [prevRow, prevCol] = position[step - 1];
    const [row, col] = position[step];
    const rowDiff = Math.abs(row - prevRow);
    const colDiff = Math.abs(col - prevCol);
    const isKnightMove = (rowDiff === 1 && colDiff === 2) || (rowDiff === 2 && colDiff === 1);
    if (!isKnightMove) {
      return false;
    }
  }
  return true;
}

