function checkValidGrid(grid) {
  const n = grid.length;
  const jumps = [[1, 2], [2, 1], [-1, 2], [-2, 1], [1, -2], [2, -1], [-1, -2], [-2, -1]];
  let r = 0;
  let c = 0;
  if (grid[r][c] !== 0) return false;
  for (let want = 1; want < n * n; want++) {
    let moved = false;
    for (const [dr, dc] of jumps) {
      const a = r + dr, b = c + dc;
      if (a >= 0 && b >= 0 && a < n && b < n && grid[a][b] === want) {
        r = a;
        c = b;
        moved = true;
        break;
      }
    }
    if (!moved) return false;
  }
  return true;
}

