function generate(rand, size) {
  const jumps = [[1, 2], [2, 1], [-1, 2], [-2, 1], [1, -2], [2, -1], [-1, -2], [-2, -1]];
  const tour = (n) => {
    // Warnsdorff's rule with random tie-breaking: always jump to the free cell with the fewest onward jumps.
    for (;;) {
      const grid = Array.from({ length: n }, () => new Array(n).fill(-1));
      let r = 0, c = 0, ok = true;
      grid[0][0] = 0;
      const free = (a, b) => a >= 0 && b >= 0 && a < n && b < n && grid[a][b] === -1;
      const degree = (a, b) => jumps.filter(([x, y]) => free(a + x, b + y)).length;
      for (let step = 1; step < n * n && ok; step++) {
        let best = null, bestDegree = 9, ties = 0;
        for (const [x, y] of jumps) {
          if (!free(r + x, c + y)) continue;
          const d = degree(r + x, c + y);
          if (d < bestDegree) { best = [r + x, c + y]; bestDegree = d; ties = 1; }
          else if (d === bestDegree && rand() * ++ties < 1) best = [r + x, c + y];
        }
        if (!best) ok = false;
        else { [r, c] = best; grid[r][c] = step; }
      }
      if (ok) return grid;
    }
  };
  const swap = (grid, a, b) => grid.map(line => line.map(v => (v === a ? b : v === b ? a : v)));
  const mode = rand();
  const n = size === 'large' ? 5 + Math.floor(rand() * 3) : 3 + Math.floor(rand() * 5);
  const last = n * n - 1;
  if (mode < 0.2 || n < 5) {
    const values = Array.from({ length: last }, (_, k) => k + 1);
    for (let k = values.length - 1; k > 0; k--) {
      const j = Math.floor(rand() * (k + 1));
      [values[k], values[j]] = [values[j], values[k]];
    }
    values.unshift(0);
    return [Array.from({ length: n }, (_, row) => values.slice(row * n, row * n + n))];
  }
  const grid = tour(n);
  if (mode < 0.55) return [grid];
  if (mode < 0.75) {
    const a = 1 + Math.floor(rand() * last);
    const b = rand() < 0.5 ? Math.min(last, a + 1) : 1 + Math.floor(rand() * last);
    return [swap(grid, a, b)];
  }
  if (mode < 0.85) return [grid.map(line => line.map(v => last - v))];
  if (mode < 0.92) return [grid.map(line => line.slice().reverse())];
  return [swap(grid, 0, 1 + Math.floor(rand() * last))];
}
